// Node "Prepare": which repository and file the backup goes to.
const exp = $input.first().json || {};
const repo = typeof exp.repo === 'string' ? exp.repo.trim() : '';
const today = /^\d{4}-\d{2}-\d{2}$/.test(exp.today || '') ? exp.today : '';
const okRepo = /^[A-Za-z0-9_.-]{1,100}\/[A-Za-z0-9_.-]{1,100}$/.test(repo);
return [{ json: { repo: okRepo ? repo : '', today, path: `backups/jarvis-${today || 'undated'}.json` } }];

// Node "Build file": checks the repository is private, then packs the backup for GitHub's contents API.
const exp = $('Export').first().json || {};
const prep = $('Prepare').first().json || {};
const repoInfo = $('Check repo').first().json || {};
const existing = $input.first().json || {};
const data = typeof exp.data === 'string' ? exp.data : '';
const fail = (error) => [{ json: { content: '', error } }];

if (!prep.repo) return fail('No backup repository is set. Set it with: update jarvis.settings set value = \'"owner/repo"\' where key = \'backup_repo\';');
if (!prep.today) return fail('Could not work out today\'s date.');
if (!data) return fail('The export came back empty.');
if (data.length > 20 * 1024 * 1024) return fail('The backup is too large for one file.');
const status = Number(repoInfo.statusCode) || 0;
if (status === 401) return fail('GitHub rejected the token. Make a new one and update the GitHub backup token credential in n8n.');
if (status === 404) return fail(`GitHub cannot find ${prep.repo}, or the token has no access to it.`);
if (status < 200 || status >= 300) return fail(`GitHub answered HTTP ${status || 'nothing'} when checking the repository.`);
const info = repoInfo.body && typeof repoInfo.body === 'object' ? repoInfo.body : {};
if (info.private !== true) return fail(`${prep.repo} is not private. Make the repository private before backing up into it.`);

let counts = {};
try {
  const t = JSON.parse(data).tables || {};
  for (const k of Object.keys(t)) counts[k] = Array.isArray(t[k]) ? t[k].length : 0;
} catch (e) { return fail('The export was not valid JSON.'); }

const sha = existing.statusCode === 200 && existing.body && typeof existing.body.sha === 'string' ? existing.body.sha : '';
const body = { message: `Jarvis backup ${prep.today}`, content: Buffer.from(data, 'utf8').toString('base64') };
if (sha) body.sha = sha;
return [{ json: { repo: prep.repo, path: prep.path, put_body: JSON.stringify(body), bytes: data.length, counts, replaced: !!sha } }];

// Node "Backup result": what happened when the backup went to GitHub.
const built = $('Build file').first().json || {};
const res = $input.first().json || {};
const status = Number(res.statusCode) || 0;
const ok = !built.error && (status === 200 || status === 201);
let why = built.error || '';
if (!ok && !why) {
  const msg = res.body && typeof res.body === 'object' && typeof res.body.message === 'string' ? res.body.message.slice(0, 120) : '';
  why = `GitHub refused it (HTTP ${status || 'no answer'}${msg ? ': ' + msg : ''}).`;
}
const rows = Object.values(built.counts || {}).reduce((a, b) => a + b, 0);
const reply = ok
  ? `Backup saved to GitHub (${Math.round((built.bytes || 0) / 1024)} KB, ${rows} rows${built.replaced ? ', replaced today\'s file' : ''}).`
  : `Backup failed. ${why}`;
return [{ json: { ok, reply, why, bytes: built.bytes || 0, counts: built.counts || {} } }];

// Node "Backup problem": a failed backup becomes an alert.
const r = $input.first().json || {};
return [{ json: { problems: [{ key: 'backup', text: String(r.reply || 'Backup failed.').slice(0, 200) }] } }];

// Node "Health check": looks for things that stopped working quietly. Each problem has a key so it is only reported once per 6 hours.
const h = $input.first().json || {};
const now = Date.now();
const hoursSince = (s) => { const t = Date.parse(s); return Number.isFinite(t) ? (now - t) / 3600000 : null; };
const problems = [];

const st = h.email_status && typeof h.email_status === 'object' ? h.email_status : {};
for (const acct of ['personal', 'college']) {
  if (typeof st[acct] === 'string' && st[acct]) {
    problems.push({ key: 'email-' + acct, text: `Gmail (${acct}) cannot be read: ${st[acct].slice(0, 100)}. Reconnect it in n8n.` });
  }
}
const sync = hoursSince(h.email_synced_at);
if (sync !== null && sync > 4) problems.push({ key: 'email-stale', text: `Email has not been checked for ${Math.round(sync)} hours.` });

const bk = hoursSince(h.backup_last_ok);
if (bk !== null && bk > 36) problems.push({ key: 'backup-stale', text: `No successful backup for ${Math.round(bk / 24 * 10) / 10} days.` });

const missed = Number(h.missed_reminders) || 0;
if (missed > 0) problems.push({ key: 'missed', text: `${missed} reminder${missed === 1 ? ' was' : 's were'} due over 90 minutes ago and never fired.` });

return [{ json: { problems } }];

// Node "Error to problem": a workflow that crashed becomes an alert.
const e = $input.first().json || {};
const wf = (e.workflow && e.workflow.name) || 'A workflow';
if (/^09\b/.test(wf)) return [];
const ex = e.execution || {};
const err = ex.error || {};
const msg = String(err.message || 'unknown error').replace(/\s+/g, ' ').slice(0, 140);
const where = ex.lastNodeExecuted ? ` at "${String(ex.lastNodeExecuted).slice(0, 40)}"` : '';
return [{ json: { problems: [{ key: 'wf:' + wf, text: `${wf} failed${where}: ${msg}` }] } }];

// Node "Decide": drops problems already reported in the last 6 hours and builds one push for the rest.
const st = $input.first().json || {};
const problems = Array.isArray(st.problems) ? st.problems.filter((p) => p && typeof p.key === 'string' && typeof p.text === 'string') : [];
const alerts = st.alerts && typeof st.alerts === 'object' && !Array.isArray(st.alerts) ? st.alerts : {};
const now = Date.now();
const WINDOW = 6 * 3600000;
const fresh = problems.filter((p) => { const t = Date.parse(alerts[p.key]); return !(Number.isFinite(t) && now - t < WINDOW); });
const key = typeof st.bark_key === 'string' ? st.bark_key : '';
if (!fresh.length || !key) return [{ json: { send: false, found: problems.length } }];
const next = {};
for (const k of Object.keys(alerts)) { const t = Date.parse(alerts[k]); if (Number.isFinite(t) && now - t < 3 * 86400000) next[k] = alerts[k]; }
for (const p of fresh) next[p.key] = new Date(now).toISOString();
const body = fresh.map((p) => p.text).join('\n').slice(0, 480);
return [{ json: { send: true, bark_key: key, title: fresh.length === 1 ? 'Jarvis needs attention' : `Jarvis: ${fresh.length} problems`, body, alerts_json: JSON.stringify(next), found: problems.length } }];

// Node "Reply": the answer to the backup webhook (the scheduled runs ignore it).
let r = null;
try { r = $('Backup result').first().json; } catch (e) { r = null; }
return [{ json: r ? { ok: !!r.ok, reply: String(r.reply || '') } : { ok: true, reply: 'Done.' } }];
